=head1 MESSAGES

=head2 Google::Cloud::Translation::V3::TranslationService::TransliterationConfig

Configures transliteration feature on top of translation.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->enable_transliteration() >> / C<< $msg->enable_transliteration($value) >>

Type: C<Bool>

If true, source text in romanized form can be translated to the target
language.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::TranslateTextRequest

The request message for synchronous translation.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->contents() >> / C<< $msg->contents($value) >>

Type: C<String>

Required. The content of the input in string format.
We recommend the total content be less than 30,000 codepoints. The max
length of this field is 1024. Use BatchTranslateText for larger text.

=item * C<< $msg->mime_type() >> / C<< $msg->mime_type($value) >>

Type: C<String>

Optional. The format of the source text, for example, "text/html",
 "text/plain". If left blank, the MIME type defaults to "text/html".

=item * C<< $msg->source_language_code() >> / C<< $msg->source_language_code($value) >>

Type: C<String>

Optional. The ISO-639 language code of the input text if
known, for example, "en-US" or "sr-Latn". Supported language codes are
listed in [Language
Support](https://cloud.google.com/translate/docs/languages). If the source
language isn't specified, the API attempts to identify the source language
automatically and returns the source language within the response.

=item * C<< $msg->target_language_code() >> / C<< $msg->target_language_code($value) >>

Type: C<String>

Required. The ISO-639 language code to use for translation of the input
text, set to one of the language codes listed in [Language
Support](https://cloud.google.com/translate/docs/languages).

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. Project or location to make a call. Must refer to a caller's
project.

Format: `projects/{project-number-or-id}` or
`projects/{project-number-or-id}/locations/{location-id}`.

For global calls, use `projects/{project-number-or-id}/locations/global` or
`projects/{project-number-or-id}`.

Non-global location is required for requests using AutoML models or
custom glossaries.

Models and glossaries must be within the same region (have same
location-id), otherwise an INVALID_ARGUMENT (400) error is returned.

=item * C<< $msg->model() >> / C<< $msg->model($value) >>

Type: C<String>

Optional. The `model` type requested for this translation.

The format depends on model type:

- AutoML Translation models:
  `projects/{project-number-or-id}/locations/{location-id}/models/{model-id}`

- General (built-in) models:
  `projects/{project-number-or-id}/locations/{location-id}/models/general/nmt`,

- Translation LLM models:
  `projects/{project-number-or-id}/locations/{location-id}/models/general/translation-llm`,

For global (non-regionalized) requests, use `location-id` `global`.
For example,
`projects/{project-number-or-id}/locations/global/models/general/nmt`.

If not provided, the default Google model (NMT) will be used

=item * C<< $msg->glossary_config() >> / C<< $msg->glossary_config($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::TranslateTextGlossaryConfig>)

Optional. Glossary to be applied. The glossary must be
within the same region (have the same location-id) as the model, otherwise
an INVALID_ARGUMENT (400) error is returned.

=item * C<< $msg->transliteration_config() >> / C<< $msg->transliteration_config($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::TransliterationConfig>)

Optional. Transliteration to be applied.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::TranslateTextRequest::LabelsEntry>)

Optional. The labels with user-defined metadata for the request.

Label keys and values can be no longer than 63 characters
(Unicode codepoints), can only contain lowercase letters, numeric
characters, underscores and dashes. International characters are allowed.
Label values are optional. Label keys must start with a letter.

See https://cloud.google.com/translate/docs/advanced/labels for more
