=head2 Google::Cloud::Translation::V3::TranslationService::Translation

A single translation response.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->translated_text() >> / C<< $msg->translated_text($value) >>

Type: C<String>

