If an error occurs during translation, this field might be excluded from
the response.

=item * C<< $msg->model() >> / C<< $msg->model($value) >>

Type: C<String>

Only present when `model` is present in the request.
`model` here is normalized to have project number.

For example:
If the `model` requested in TranslationTextRequest is
`projects/{project-id}/locations/{location-id}/models/general/nmt` then
`model` here would be normalized to
`projects/{project-number}/locations/{location-id}/models/general/nmt`.

=item * C<< $msg->detected_language_code() >> / C<< $msg->detected_language_code($value) >>

Type: C<String>

The ISO-639 language code of source text in the initial request, detected
automatically, if no source language was passed within the initial
request. If the source language was passed, auto-detection of the language
does not occur and this field is empty.

=item * C<< $msg->glossary_config() >> / C<< $msg->glossary_config($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::TranslateTextGlossaryConfig>)

The `glossary_config` used for this translation.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::RomanizeTextRequest

