=head2 Google::Cloud::Translation::V3::TranslationService::GcsSource

The Google Cloud Storage location for the input content.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->input_uri() >> / C<< $msg->input_uri($value) >>

Type: C<String>

Required. Source data URI. For example, `gs://my_bucket/my_object`.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::InputConfig

Input configuration for BatchTranslateText request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->mime_type() >> / C<< $msg->mime_type($value) >>

Type: C<String>

Optional. Can be "text/plain" or "text/html".
For `.tsv`, "text/html" is used if mime_type is missing.
For `.html`, this field must be "text/html" or empty.
For `.txt`, this field must be "text/plain" or empty.

=item * C<< $msg->gcs_source() >> / C<< $msg->gcs_source($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::GcsSource>)

Required. Google Cloud Storage location for the source input.
This can be a single file (for example,
`gs://translation-test/input.tsv`) or a wildcard (for example,
`gs://translation-test/*`). If a file extension is `.tsv`, it can
contain either one or two columns. The first column (optional) is the id
of the text request. If the first column is missing, we use the row
number (0-based) from the input file as the ID in the output file. The
second column is the actual text to be
 translated. We recommend each row be <= 10K Unicode codepoints,
otherwise an error might be returned.
Note that the input tsv must be RFC 4180 compliant.

You could use https://github.com/Clever/csvlint to check potential
formatting errors in your tsv file.
csvlint --delimiter='\t' your_input_file.tsv

The other supported file extensions are `.txt` or `.html`, which is
treated as a single large chunk of text.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::GcsDestination

The Google Cloud Storage location for the output content.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->output_uri_prefix() >> / C<< $msg->output_uri_prefix($value) >>

Type: C<String>

Required. The bucket used in 'output_uri_prefix' must exist and there must
be no files under 'output_uri_prefix'. 'output_uri_prefix' must end with
"/" and start with "gs://". One 'output_uri_prefix' can only be used by one
batch translation job at a time. Otherwise an INVALID_ARGUMENT (400) error
is returned.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::OutputConfig

Output configuration for BatchTranslateText request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->gcs_destination() >> / C<< $msg->gcs_destination($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::GcsDestination>)

Google Cloud Storage destination for output content.
For every single input file (for example, gs://a/b/c.[extension]), we
generate at most 2 * n output files. (n is the # of target_language_codes
in the BatchTranslateTextRequest).

Output files (tsv) generated are compliant with RFC 4180 except that
record delimiters are '\n' instead of '\r\n'. We don't provide any way to
change record delimiters.

While the input files are being processed, we write/update an index file
'index.csv'  under 'output_uri_prefix' (for example,
gs://translation-test/index.csv) The index file is generated/updated as
new files are being translated. The format is:

input_file,target_language_code,translations_file,errors_file,
glossary_translations_file,glossary_errors_file

input_file is one file we matched using gcs_source.input_uri.
target_language_code is provided in the request.
translations_file contains the translations. (details provided below)
errors_file contains the errors during processing of the file. (details
below). Both translations_file and errors_file could be empty
strings if we have no content to output.
glossary_translations_file and glossary_errors_file are always empty
strings if the input_file is tsv. They could also be empty if we have no
content to output.

Once a row is present in index.csv, the input/output matching never
changes. Callers should also expect all the content in input_file are
processed and ready to be consumed (that is, no partial output file is
written).

Since index.csv will be keeping updated during the process, please make
sure there is no custom retention policy applied on the output bucket
that may avoid file updating.
(https://cloud.google.com/storage/docs/bucket-lock#retention-policy)

The format of translations_file (for target language code 'trg') is:
`gs://translation_test/a_b_c_'trg'_translations.[extension]`

If the input file extension is tsv, the output has the following
columns:
Column 1: ID of the request provided in the input, if it's not
provided in the input, then the input row number is used (0-based).
Column 2: source sentence.
Column 3: translation without applying a glossary. Empty string if there
is an error.
Column 4 (only present if a glossary is provided in the request):
translation after applying the glossary. Empty string if there is an
error applying the glossary. Could be same string as column 3 if there is
no glossary applied.

If input file extension is a txt or html, the translation is directly
written to the output file. If glossary is requested, a separate
glossary_translations_file has format of
`gs://translation_test/a_b_c_'trg'_glossary_translations.[extension]`

The format of errors file (for target language code 'trg') is:
`gs://translation_test/a_b_c_'trg'_errors.[extension]`

If the input file extension is tsv, errors_file contains the following:
Column 1: ID of the request provided in the input, if it's not
provided in the input, then the input row number is used (0-based).
Column 2: source sentence.
Column 3: Error detail for the translation. Could be empty.
Column 4 (only present if a glossary is provided in the request):
Error when applying the glossary.

If the input file extension is txt or html, glossary_error_file will be
generated that contains error details. glossary_error_file has format of
`gs://translation_test/a_b_c_'trg'_glossary_errors.[extension]`

=back

=head2 Google::Cloud::Translation::V3::TranslationService::DocumentInputConfig

A document translation request input config.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->content() >> / C<< $msg->content($value) >>

Type: C<Bytes>

Document's content represented as a stream of bytes.

=item * C<< $msg->gcs_source() >> / C<< $msg->gcs_source($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::GcsSource>)

Google Cloud Storage location. This must be a single file.
For example: gs://example_bucket/example_file.pdf

=item * C<< $msg->mime_type() >> / C<< $msg->mime_type($value) >>

Type: C<String>

Specifies the input document's mime_type.

If not specified it will be determined using the file extension for
gcs_source provided files. For a file provided through bytes content the
mime_type must be provided.
Currently supported mime types are:
- application/pdf
- application/vnd.openxmlformats-officedocument.wordprocessingml.document
- application/vnd.openxmlformats-officedocument.presentationml.presentation
- application/vnd.openxmlformats-officedocument.spreadsheetml.sheet

=back

=head2 Google::Cloud::Translation::V3::TranslationService::DocumentOutputConfig

A document translation request output config.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->gcs_destination() >> / C<< $msg->gcs_destination($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::GcsDestination>)

Optional. Google Cloud Storage destination for the translation output,
e.g., `gs://my_bucket/my_directory/`.

The destination directory provided does not have to be empty, but the
bucket must exist. If a file with the same name as the output file
already exists in the destination an error will be returned.

For a DocumentInputConfig.contents provided document, the output file
will have the name "output_[trg]_translations.[ext]", where
- [trg] corresponds to the translated file's language code,
- [ext] corresponds to the translated file's extension according to its
mime type.


For a DocumentInputConfig.gcs_uri provided document, the output file will
have a name according to its URI. For example: an input file with URI:
`gs://a/b/c.[extension]` stored in a gcs_destination bucket with name
"my_bucket" will have an output URI:
`gs://my_bucket/a_b_c_[trg]_translations.[ext]`, where
- [trg] corresponds to the translated file's language code,
- [ext] corresponds to the translated file's extension according to its
mime type.


If the document was directly provided through the request, then the
output document will have the format:
`gs://my_bucket/translated_document_[trg]_translations.[ext]`, where
- [trg] corresponds to the translated file's language code,
- [ext] corresponds to the translated file's extension according to its
mime type.

If a glossary was provided, then the output URI for the glossary
translation will be equal to the default output URI but have
`glossary_translations` instead of `translations`. For the previous
example, its glossary URI would be:
`gs://my_bucket/a_b_c_[trg]_glossary_translations.[ext]`.

Thus the max number of output files will be 2 (Translated document,
Glossary translated document).

Callers should expect no partial outputs. If there is any error during
document translation, no output will be stored in the Cloud Storage
bucket.

=item * C<< $msg->mime_type() >> / C<< $msg->mime_type($value) >>

Type: C<String>

Optional. Specifies the translated document's mime_type.
If not specified, the translated file's mime type will be the same as the
input file's mime type.
Currently only support the output mime type to be the same as input mime
type.
- application/pdf
- application/vnd.openxmlformats-officedocument.wordprocessingml.document
- application/vnd.openxmlformats-officedocument.presentationml.presentation
- application/vnd.openxmlformats-officedocument.spreadsheetml.sheet

=back

=head2 Google::Cloud::Translation::V3::TranslationService::TranslateDocumentRequest

A document translation request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. Location to make a regional call.

Format: `projects/{project-number-or-id}/locations/{location-id}`.

For global calls, use `projects/{project-number-or-id}/locations/global` or
`projects/{project-number-or-id}`.

Non-global location is required for requests using AutoML models or custom
glossaries.

Models and glossaries must be within the same region (have the same
location-id), otherwise an INVALID_ARGUMENT (400) error is returned.

=item * C<< $msg->source_language_code() >> / C<< $msg->source_language_code($value) >>

Type: C<String>

Optional. The ISO-639 language code of the input document if known, for
example, "en-US" or "sr-Latn". Supported language codes are listed in
[Language Support](https://cloud.google.com/translate/docs/languages). If
the source language isn't specified, the API attempts to identify the
source language automatically and returns the source language within the
response. Source language must be specified if the request contains a
glossary or a custom model.

=item * C<< $msg->target_language_code() >> / C<< $msg->target_language_code($value) >>

Type: C<String>

Required. The ISO-639 language code to use for translation of the input
document, set to one of the language codes listed in [Language
Support](https://cloud.google.com/translate/docs/languages).

=item * C<< $msg->document_input_config() >> / C<< $msg->document_input_config($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::DocumentInputConfig>)

Required. Input configurations.

=item * C<< $msg->document_output_config() >> / C<< $msg->document_output_config($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::DocumentOutputConfig>)

Optional. Output configurations.
Defines if the output file should be stored within Cloud Storage as well
as the desired output format. If not provided the translated file will
only be returned through a byte-stream and its output mime type will be
the same as the input file's mime type.

=item * C<< $msg->model() >> / C<< $msg->model($value) >>

Type: C<String>

Optional. The `model` type requested for this translation.

The format depends on model type:

- AutoML Translation models:
  `projects/{project-number-or-id}/locations/{location-id}/models/{model-id}`

- General (built-in) models:
  `projects/{project-number-or-id}/locations/{location-id}/models/general/nmt`,


If not provided, the default Google model (NMT) will be used for
translation.

=item * C<< $msg->glossary_config() >> / C<< $msg->glossary_config($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::TranslateTextGlossaryConfig>)

Optional. Glossary to be applied. The glossary must be within the same
region (have the same location-id) as the model, otherwise an
INVALID_ARGUMENT (400) error is returned.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::TranslateDocumentRequest::LabelsEntry>)

Optional. The labels with user-defined metadata for the request.

Label keys and values can be no longer than 63 characters (Unicode
codepoints), can only contain lowercase letters, numeric characters,
underscores and dashes. International characters are allowed. Label values
are optional. Label keys must start with a letter.

See https://cloud.google.com/translate/docs/advanced/labels for more
information.

=item * C<< $msg->customized_attribution() >> / C<< $msg->customized_attribution($value) >>

Type: C<String>

Optional. This flag is to support user customized attribution.
If not provided, the default is `Machine Translated by Google`.
Customized attribution should follow rules in
https://cloud.google.com/translate/attribution#attribution_and_logos

=item * C<< $msg->is_translate_native_pdf_only() >> / C<< $msg->is_translate_native_pdf_only($value) >>

Type: C<Bool>

Optional. is_translate_native_pdf_only field for external customers.
If true, the page limit of online native pdf translation is 300 and only
native pdf pages will be translated.

=item * C<< $msg->enable_shadow_removal_native_pdf() >> / C<< $msg->enable_shadow_removal_native_pdf($value) >>

Type: C<Bool>

Optional. If true, use the text removal server to remove the shadow text on
background image for native pdf translation.
Shadow removal feature can only be enabled when
is_translate_native_pdf_only: false && pdf_native_only: false

=item * C<< $msg->enable_rotation_correction() >> / C<< $msg->enable_rotation_correction($value) >>

Type: C<Bool>

Optional. If true, enable auto rotation correction in DVS.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::DocumentTranslation

A translated document message.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->byte_stream_outputs() >> / C<< $msg->byte_stream_outputs($value) >>

Type: C<Bytes>

The array of translated documents. It is expected to be size 1 for now. We
