=item * C<< $msg->mime_type() >> / C<< $msg->mime_type($value) >>

Type: C<String>

The translated document's mime type.

=item * C<< $msg->detected_language_code() >> / C<< $msg->detected_language_code($value) >>

Type: C<String>

The detected language for the input document.
If the user did not provide the source language for the input document,
this field will have the language code automatically detected. If the
source language was passed, auto-detection of the language does not occur
and this field is empty.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::TranslateDocumentResponse

A translated document response message.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->document_translation() >> / C<< $msg->document_translation($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::DocumentTranslation>)

Translated document.

=item * C<< $msg->glossary_document_translation() >> / C<< $msg->glossary_document_translation($value) >>

