=head2 Google::Cloud::Translation::V3::TranslationService::BatchTranslateDocumentRequest

The BatchTranslateDocument request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. Location to make a regional call.

Format: `projects/{project-number-or-id}/locations/{location-id}`.

The `global` location is not supported for batch translation.

Only AutoML Translation models or glossaries within the same region (have
the same location-id) can be used, otherwise an INVALID_ARGUMENT (400)
error is returned.

=item * C<< $msg->source_language_code() >> / C<< $msg->source_language_code($value) >>

Type: C<String>

Required. The ISO-639 language code of the input document if known, for
example, "en-US" or "sr-Latn". Supported language codes are listed in
[Language Support](https://cloud.google.com/translate/docs/languages).

=item * C<< $msg->target_language_codes() >> / C<< $msg->target_language_codes($value) >>

Type: C<String>

Required. The ISO-639 language code to use for translation of the input
document. Specify up to 10 language codes here. Supported language codes
are listed in [Language
Support](https://cloud.google.com/translate/docs/languages).

=item * C<< $msg->input_configs() >> / C<< $msg->input_configs($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::BatchDocumentInputConfig>)

Required. Input configurations.
The total number of files matched should be <= 100.
The total content size to translate should be <= 100M Unicode codepoints.
The files must use UTF-8 encoding.

=item * C<< $msg->output_config() >> / C<< $msg->output_config($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::BatchDocumentOutputConfig>)

Required. Output configuration.
If 2 input configs match to the same file (that is, same input path),
we don't generate output for duplicate inputs.

=item * C<< $msg->models() >> / C<< $msg->models($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::BatchTranslateDocumentRequest::ModelsEntry>)

Optional. The models to use for translation. Map's key is target language
code. Map's value is the model name. Value can be a built-in general model,
or an AutoML Translation model.

The value format depends on model type:

- AutoML Translation models:
  `projects/{project-number-or-id}/locations/{location-id}/models/{model-id}`

- General (built-in) models:
  `projects/{project-number-or-id}/locations/{location-id}/models/general/nmt`,


If the map is empty or a specific model is
not requested for a language pair, then default google model (nmt) is used.

=item * C<< $msg->glossaries() >> / C<< $msg->glossaries($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::BatchTranslateDocumentRequest::GlossariesEntry>)

Optional. Glossaries to be applied. It's keyed by target language code.

=item * C<< $msg->format_conversions() >> / C<< $msg->format_conversions($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::BatchTranslateDocumentRequest::FormatConversionsEntry>)

Optional. The file format conversion map that is applied to all input
files. The map key is the original mime_type. The map value is the target
mime_type of translated documents.

Supported file format conversion includes:
- `application/pdf` to
  `application/vnd.openxmlformats-officedocument.wordprocessingml.document`

If nothing specified, output files will be in the same format as the
original file.

=item * C<< $msg->customized_attribution() >> / C<< $msg->customized_attribution($value) >>

Type: C<String>

Optional. This flag is to support user customized attribution.
If not provided, the default is `Machine Translated by Google`.
Customized attribution should follow rules in
https://cloud.google.com/translate/attribution#attribution_and_logos

=item * C<< $msg->enable_shadow_removal_native_pdf() >> / C<< $msg->enable_shadow_removal_native_pdf($value) >>

Type: C<Bool>

Optional. If true, use the text removal server to remove the shadow text on
background image for native pdf translation.
Shadow removal feature can only be enabled when
is_translate_native_pdf_only: false && pdf_native_only: false

=item * C<< $msg->enable_rotation_correction() >> / C<< $msg->enable_rotation_correction($value) >>

Type: C<Bool>

Optional. If true, enable auto rotation correction in DVS.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::BatchDocumentInputConfig

Input configuration for BatchTranslateDocument request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->gcs_source() >> / C<< $msg->gcs_source($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::GcsSource>)

Google Cloud Storage location for the source input.
This can be a single file (for example,
`gs://translation-test/input.docx`) or a wildcard (for example,
`gs://translation-test/*`).

File mime type is determined based on extension. Supported mime type
includes:
- `pdf`, application/pdf
- `docx`,
application/vnd.openxmlformats-officedocument.wordprocessingml.document
- `pptx`,
application/vnd.openxmlformats-officedocument.presentationml.presentation
- `xlsx`,
application/vnd.openxmlformats-officedocument.spreadsheetml.sheet

The max file size to support for `.docx`, `.pptx` and `.xlsx` is 100MB.
The max file size to support for `.pdf` is 1GB and the max page limit is
1000 pages.
The max file size to support for all input documents is 1GB.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::BatchDocumentOutputConfig

Output configuration for BatchTranslateDocument request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->gcs_destination() >> / C<< $msg->gcs_destination($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3::TranslationService::GcsDestination>)

Google Cloud Storage destination for output content.
For every single input document (for example, gs://a/b/c.[extension]), we
generate at most 2 * n output files. (n is the # of target_language_codes
in the BatchTranslateDocumentRequest).

While the input documents are being processed, we write/update an index
file `index.csv` under `gcs_destination.output_uri_prefix` (for example,
gs://translation_output/index.csv) The index file is generated/updated as
new files are being translated. The format is:

input_document,target_language_code,translation_output,error_output,
glossary_translation_output,glossary_error_output

`input_document` is one file we matched using gcs_source.input_uri.
`target_language_code` is provided in the request.
`translation_output` contains the translations. (details provided below)
`error_output` contains the error message during processing of the file.
Both translations_file and errors_file could be empty strings if we have
no content to output.
`glossary_translation_output` and `glossary_error_output` are the
translated output/error when we apply glossaries. They could also be
empty if we have no content to output.

Once a row is present in index.csv, the input/output matching never
changes. Callers should also expect all the content in input_file are
processed and ready to be consumed (that is, no partial output file is
written).

Since index.csv will be keeping updated during the process, please make
sure there is no custom retention policy applied on the output bucket
that may avoid file updating.
(https://cloud.google.com/storage/docs/bucket-lock#retention-policy)

The naming format of translation output files follows (for target
language code [trg]): `translation_output`:
`gs://translation_output/a_b_c_[trg]_translation.[extension]`
`glossary_translation_output`:
`gs://translation_test/a_b_c_[trg]_glossary_translation.[extension]`. The
output document will maintain the same file format as the input document.

The naming format of error output files follows (for target language code
[trg]): `error_output`: `gs://translation_test/a_b_c_[trg]_errors.txt`
`glossary_error_output`:
`gs://translation_test/a_b_c_[trg]_glossary_translation.txt`. The error
output is a txt file containing error details.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::BatchTranslateDocumentResponse

Stored in the
[google.longrunning.Operation.response][google.longrunning.Operation.response]
field returned by BatchTranslateDocument if at least one document is
translated successfully.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->total_pages() >> / C<< $msg->total_pages($value) >>

Type: C<Int64>

Total number of pages to translate in all documents. Documents without
clear page definition (such as XLSX) are not counted.

=item * C<< $msg->translated_pages() >> / C<< $msg->translated_pages($value) >>

Type: C<Int64>

Number of successfully translated pages in all documents. Documents without
clear page definition (such as XLSX) are not counted.

=item * C<< $msg->failed_pages() >> / C<< $msg->failed_pages($value) >>

Type: C<Int64>

Number of pages that failed to process in all documents. Documents without
clear page definition (such as XLSX) are not counted.

=item * C<< $msg->total_billable_pages() >> / C<< $msg->total_billable_pages($value) >>

Type: C<Int64>

Number of billable pages in documents with clear page definition (such as
PDF, DOCX, PPTX)

=item * C<< $msg->total_characters() >> / C<< $msg->total_characters($value) >>

Type: C<Int64>

Total number of characters (Unicode codepoints) in all documents.

=item * C<< $msg->translated_characters() >> / C<< $msg->translated_characters($value) >>

Type: C<Int64>

Number of successfully translated characters (Unicode codepoints) in all
documents.

=item * C<< $msg->failed_characters() >> / C<< $msg->failed_characters($value) >>

Type: C<Int64>

Number of characters that have failed to process (Unicode codepoints) in
all documents.

=item * C<< $msg->total_billable_characters() >> / C<< $msg->total_billable_characters($value) >>

Type: C<Int64>

Number of billable characters (Unicode codepoints) in documents without
clear page definition, such as XLSX.

=item * C<< $msg->submit_time() >> / C<< $msg->submit_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time when the operation was submitted.

=item * C<< $msg->end_time() >> / C<< $msg->end_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The time when the operation is finished and
[google.longrunning.Operation.done][google.longrunning.Operation.done] is
set to true.

=back

=head2 Google::Cloud::Translation::V3::TranslationService::BatchTranslateDocumentMetadata

State metadata for the batch translation operation.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Translation::V3::BatchTranslateDocumentMetadata::State>)

The state of the operation.

=item * C<< $msg->total_pages() >> / C<< $msg->total_pages($value) >>

Type: C<Int64>

Total number of pages to translate in all documents so far. Documents
without clear page definition (such as XLSX) are not counted.

=item * C<< $msg->translated_pages() >> / C<< $msg->translated_pages($value) >>

Type: C<Int64>

Number of successfully translated pages in all documents so far. Documents
without clear page definition (such as XLSX) are not counted.

=item * C<< $msg->failed_pages() >> / C<< $msg->failed_pages($value) >>

Type: C<Int64>

Number of pages that failed to process in all documents so far. Documents
without clear page definition (such as XLSX) are not counted.

=item * C<< $msg->total_billable_pages() >> / C<< $msg->total_billable_pages($value) >>

Type: C<Int64>

Number of billable pages in documents with clear page definition (such as
PDF, DOCX, PPTX) so far.

=item * C<< $msg->total_characters() >> / C<< $msg->total_characters($value) >>

Type: C<Int64>

Total number of characters (Unicode codepoints) in all documents so far.

=item * C<< $msg->translated_characters() >> / C<< $msg->translated_characters($value) >>

Type: C<Int64>

Number of successfully translated characters (Unicode codepoints) in all
documents so far.

=item * C<< $msg->failed_characters() >> / C<< $msg->failed_characters($value) >>

Type: C<Int64>

Number of characters that have failed to process (Unicode codepoints) in
all documents so far.

=item * C<< $msg->total_billable_characters() >> / C<< $msg->total_billable_characters($value) >>

Type: C<Int64>

Number of billable characters (Unicode codepoints) in documents without
clear page definition (such as XLSX) so far.

=item * C<< $msg->submit_time() >> / C<< $msg->submit_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Time when the operation was submitted.

=back

=head3 Enum: BatchTranslateDocumentMetadata::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<RUNNING> => C<1>

=item * C<SUCCEEDED> => C<2>

=item * C<FAILED> => C<3>

=item * C<CANCELLING> => C<4>

=item * C<CANCELLED> => C<5>

=back

=head2 Google::Cloud::Translation::V3::TranslationService::TranslateTextGlossaryConfig

Configures which glossary is used for a specific target language and defines
options for applying that glossary.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->glossary() >> / C<< $msg->glossary($value) >>

Type: C<String>

Required. The `glossary` to be applied for this translation.

The format depends on the glossary:

- User-provided custom glossary:
  `projects/{project-number-or-id}/locations/{location-id}/glossaries/{glossary-id}`

=item * C<< $msg->ignore_case() >> / C<< $msg->ignore_case($value) >>

Type: C<Bool>

Optional. Indicates match is case insensitive. The default value is `false`
if missing.

=item * C<< $msg->contextual_translation_enabled() >> / C<< $msg->contextual_translation_enabled($value) >>

Type: C<Bool>

Optional. If set to true, the glossary will be used for contextual
translation.

=back

